import React from 'react';
import { AuthProvider } from './context/AuthContext';
import AppRouter from './routes/AppRouter';

/**
 * App — point d'entrée React.
 *
 * Arborescence des providers :
 *   AuthProvider   → fournit user, token, login, logout à toute l'app
 *     AppRouter    → gère les routes publiques et privées
 */
const App = () => (
  <AuthProvider>
    <AppRouter />
  </AuthProvider>
);

export default App;
